import json,sys,os
out="tools/lead26/trial07_recovered"
files={}
for line in open(sys.argv[1]):
    try: e=json.loads(line)
    except: continue
    m=e.get("message",{})
    c=m.get("content")
    if not isinstance(c,list): continue
    for b in c:
        if b.get("type")=="tool_use" and b.get("name") in("Write","Edit"):
            i=b.get("input",{}); p=i.get("file_path","")
            if "/scratch/" in p:
                files.setdefault(p,[]).append((b["name"],i,e.get("timestamp")))
for p,ops in files.items():
    print(p, [(o[0],o[2]) for o in ops])
    content=None
    for name,i,ts in ops:
        if name=="Write": content=i.get("content")
        elif name=="Edit" and content is not None:
            if i.get("old_string") in content: content=content.replace(i["old_string"],i["new_string"],-1 if i.get("replace_all") else 1)
            else: print("  edit not applicable", ts)
    if content:
        dst=os.path.join(out,os.path.basename(p))
        open(dst,"w").write(content); print("  ->",dst,len(content))
EOF
