+<title>Rainbow Screen Check</title>
+<meta name="claude:viewport-fit-sides" content="cover">
+<link rel="preconnect" href="https://fonts.googleapis.com">
+<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;800&family=Inter:wght@400;500;600&display=swap">
+<style>
+/* Layout: one column of screen "cards"; each card = rating header + a scrolling filmstrip of phone frames (approved first) + notes. */
+:root{
+  --bg:#1b1029; --panel:#26163a; --line:#3d2758; --fg:#f6eefc; --muted:#c6b3dc;
+  --cyan:#3fd8f2; --pink:#ff5fb8; --gold:#f7b844; --good:#57d68d; --warn:#f7b844; --bad:#ff6b7a;
+  --display:"Baloo 2","Trebuchet MS",system-ui,sans-serif; --body:"Inter",system-ui,-apple-system,"Segoe UI",sans-serif;
+  color-scheme:dark;
+}
+@media (prefers-color-scheme: light){ :root:not([data-theme="dark"]){
+  --bg:#fbf6ff; --panel:#ffffff; --line:#e6d8f3; --fg:#2a1640; --muted:#6b5684;
+  --cyan:#0a8fb0; --pink:#c8247f; --gold:#a86b00; --good:#1d8a4f; --warn:#a86b00; --bad:#c42d3f; color-scheme:light } }
+:root[data-theme="light"]{
+  --bg:#fbf6ff; --panel:#ffffff; --line:#e6d8f3; --fg:#2a1640; --muted:#6b5684;
+  --cyan:#0a8fb0; --pink:#c8247f; --gold:#a86b00; --good:#1d8a4f; --warn:#a86b00; --bad:#c42d3f; color-scheme:light }
+*{box-sizing:border-box}
+body{background:var(--bg);color:var(--fg);font:15px/1.55 var(--body);margin:0}
+.wrap{max-width:1180px;margin:0 auto;padding-block:28px 64px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:grid;gap:28px}
+h1,h2,h3{font-family:var(--display);line-height:1.15;text-wrap:balance;margin:0}
+h1{font-size:clamp(30px,5vw,44px);font-weight:800}
+h1 span{background:linear-gradient(90deg,var(--cyan),var(--pink),var(--gold));-webkit-background-clip:text;background-clip:text;color:transparent}
+h2{font-size:26px;font-weight:800}
+h3{font-size:17px;font-weight:600;color:var(--muted);letter-spacing:.02em}
+p{margin:0;max-width:72ch}
+.lede{display:grid;gap:10px}
+.meta{color:var(--muted);font-size:13px}
+.panel{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:20px;display:grid;gap:16px;min-width:0}
+/* score chart */
+.chart{display:grid;gap:8px}
+.row{display:grid;grid-template-columns:150px 1fr 44px;align-items:center;gap:12px}
+.row .nm{font-weight:600;font-size:14px}
+.track{position:relative;height:18px;background:color-mix(in srgb,var(--line) 70%,transparent);border-radius:9px}
+.fill{position:absolute;inset:0 auto 0 0;border-radius:9px}
+.target{position:absolute;top:-5px;bottom:-5px;left:85%;width:2px;background:var(--fg);opacity:.75}
+.num{font-family:var(--display);font-weight:800;font-size:20px;font-variant-numeric:tabular-nums;text-align:right}
+.legend{font-size:12px;color:var(--muted)}
+@media (max-width:520px){.row{grid-template-columns:96px 1fr 38px}.row .nm{font-size:12px}}
+/* screen cards */
+.head{display:flex;flex-wrap:wrap;gap:10px 18px;align-items:baseline;justify-content:space-between}
+.pills{display:flex;gap:8px;flex-wrap:wrap}
+.pill{border:1px solid var(--line);border-radius:999px;padding:3px 12px;font-size:13px;font-weight:600;white-space:nowrap}
+.pill b{font-family:var(--display);font-size:16px}
+.lo{color:var(--bad)} .mid{color:var(--warn)} .hi{color:var(--good)}
+.tag{font-size:12px;color:var(--muted)}
+.strip{display:flex;gap:12px;overflow-x:auto;padding-bottom:8px;scroll-snap-type:x proximity}
+figure{margin:0;flex:0 0 auto;width:min(176px,40vw);display:grid;gap:6px;scroll-snap-align:start}
+.phone{aspect-ratio:9/16;max-width:100%;border-radius:18px;overflow:hidden;border:3px solid #120a1c;box-shadow:0 0 0 1px var(--line);background:#120a1c;cursor:zoom-in;padding:0;display:block;width:100%}
+.phone img{width:100%;height:100%;object-fit:cover;display:block}
