+.cols h4{margin:0 0 4px;font-size:13px;letter-spacing:.06em;text-transform:uppercase}
+.cols ul{margin:0;padding-left:18px;display:grid;gap:4px}
+.k-close{color:var(--good)} .k-diff{color:var(--pink)} .k-fix{color:var(--cyan)}
+.note{border-left:3px solid var(--gold);padding-left:12px;color:var(--muted);font-size:14px}
